import type { MaybeRefOrGetter } from 'vue';
import type { GuidedEmptyConfig } from '~/types/guidedEmpty';

/**
 * Resolves the guided empty state for the current user role and decides whether
 * it should be shown: the role has a configured entry, the list is empty, and no
 * custom filters are applied (pagination/sort and `filterDefaults` are ignored).
 *
 * @param config Guided empty config keyed by role (object, ref, or getter).
 * @param isEmpty Whether the underlying list is currently empty.
 * @param filterDefaults Filter keys whose default value should not count as an active filter.
 */
export function useGuidedEmpty(
  config: MaybeRefOrGetter<GuidedEmptyConfig>,
  isEmpty: MaybeRefOrGetter<boolean>,
  filterDefaults?: Record<string, unknown>
) {
  const { userRole } = useUserRole();
  const route = useRoute();

  const guidedContent = computed(() => toValue(config)[userRole.value] ?? null);

  const showGuided = computed(
    () => !!guidedContent.value && toValue(isEmpty) && !hasActiveFilters(route.query, filterDefaults)
  );

  return { guidedContent, showGuided };
}
