import type { LocationQuery } from 'vue-router';

const IGNORED_KEYS = ['page', 'size', 'sort_by', 'sort_type'];

function isEmptyValue(value: unknown): boolean {
  if (value === undefined || value === null) return true;
  if (Array.isArray(value)) return value.length === 0;
  if (typeof value === 'string') return value.length === 0;
  return false;
}

function normalize(value: unknown): string[] {
  if (Array.isArray(value)) return value.map((v) => String(v)).sort();
  return [String(value)];
}

function equalsDefault(value: unknown, defaultValue: unknown): boolean {
  const a = normalize(value);
  const b = normalize(defaultValue);
  return a.length === b.length && a.every((v, i) => v === b[i]);
}

/**
 * Returns true when the URL query represents a custom-filtered view.
 * Pagination and sort params are ignored. `defaults` maps filter keys to their
 * default value; a query value equal to its default does not count as active.
 */
export function hasActiveFilters(query: LocationQuery, defaults: Record<string, unknown> = {}): boolean {
  for (const [key, value] of Object.entries(query)) {
    if (IGNORED_KEYS.includes(key)) continue;
    if (isEmptyValue(value)) continue;
    if (key in defaults) {
      if (!equalsDefault(value, defaults[key])) return true;
    } else {
      return true;
    }
  }
  return false;
}
