<template>
  <component :is="variant === 'page' ? Card : 'div'" :class="cn(rootClass, props.class)">
    <component :is="variant === 'page' ? CardContent : 'div'" :class="cn('flex flex-1', variant === 'page' && '!p-0')">
      <Empty data-testid="guided-empty">
        <EmptyHeader>
          <EmptyMedia variant="icon">
            <component :is="icon" aria-hidden="true" />
          </EmptyMedia>
          <EmptyTitle>{{ title }}</EmptyTitle>
          <EmptyDescription>{{ description }}</EmptyDescription>
        </EmptyHeader>
        <EmptyContent v-if="visibleActions.length">
          <template v-for="(action, index) in visibleActions" :key="action.label">
            <NuxtLink v-if="action.to" :to="action.to" class="w-full sm:w-auto pointer-events-auto">
              <Button :variant="action.variant" class="w-full" :data-testid="`guided-empty-action-${index}`">
                {{ action.label }}
              </Button>
            </NuxtLink>
            <Button
              v-else
              :variant="action.variant"
              class="w-full sm:w-auto pointer-events-auto"
              :data-testid="`guided-empty-action-${index}`"
              @click="emit('action', action.event)"
            >
              {{ action.label }}
            </Button>
          </template>
        </EmptyContent>
      </Empty>
    </component>
  </component>
</template>

<script setup lang="ts">
import type { HTMLAttributes } from 'vue';
import { cn } from '@/lib/utils';
import { Card, CardContent } from '@/components/ui/card';

interface Props {
  icon: GuidedEmptyContent['icon'];
  title: string;
  description: string;
  variant?: 'page' | 'table';
  actions?: GuidedEmptyAction[];
  class?: HTMLAttributes['class'];
}

const props = withDefaults(defineProps<Props>(), {
  variant: 'page',
  actions: () => [],
  class: undefined,
});

const emit = defineEmits<{ action: [event?: string] }>();

const { isMobile } = useMobileForWeb();

const rootClass = computed(() => (props.variant === 'page' ? 'flex min-h-80' : 'flex min-h-48'));

const visibleActions = computed(() => props.actions.filter((action) => !action.mobileOnly || isMobile));
</script>
